package org.novasos.healthysv2.consultation;
import static org.novasos.healthysv2.consultation.Values.*;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;

@Entity @Table(name="vital_sign",schema="consultation") class VitalSign{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id",nullable=false)private Consultation consultation;private BigDecimal temperature,weight,height,bmi;@Column(name="systolic_pressure")private Integer systolic;@Column(name="diastolic_pressure")private Integer diastolic;@Column(name="heart_rate")private Integer heartRate;@Column(name="respiratory_rate")private Integer respiratoryRate;@Column(name="oxygen_saturation")private BigDecimal oxygen;@Column(name="measured_at",nullable=false)private Instant measuredAt;@Column(name="measured_by")private UUID measuredBy;protected VitalSign(){}static VitalSign create(Consultation c,BigDecimal t,BigDecimal w,BigDecimal h,Integer s,Integer d,Integer hr,Integer rr,BigDecimal o,Instant at,UUID by){var x=new VitalSign();x.id=UUID.randomUUID();x.consultation=c;x.temperature=t;x.weight=w;x.height=h;x.bmi=w!=null&&h!=null&&h.signum()>0?w.divide(h.movePointLeft(2).pow(2),2,RoundingMode.HALF_UP):null;x.systolic=s;x.diastolic=d;x.heartRate=hr;x.respiratoryRate=rr;x.oxygen=o;x.measuredAt=at==null?Instant.now():at;x.measuredBy=by;return x;}UUID getId(){return id;}BigDecimal getTemperature(){return temperature;}BigDecimal getWeight(){return weight;}BigDecimal getHeight(){return height;}BigDecimal getBmi(){return bmi;}Integer getSystolic(){return systolic;}Integer getDiastolic(){return diastolic;}Integer getHeartRate(){return heartRate;}Integer getRespiratoryRate(){return respiratoryRate;}BigDecimal getOxygen(){return oxygen;}Instant getMeasuredAt(){return measuredAt;}UUID getMeasuredBy(){return measuredBy;}}
@Entity @Table(name="diagnosis",schema="consultation") class Diagnosis{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id",nullable=false)private Consultation consultation;@Column(name="diagnosis_catalog_id")private UUID catalogId;@Column(name="diagnosis_type",length=50)private String type;@Column(columnDefinition="text")private String description;@Column(nullable=false,length=30)private String status;@Column(name="diagnosed_at",nullable=false)private Instant diagnosedAt;protected Diagnosis(){}static Diagnosis create(Consultation c,UUID catalog,String type,String description,String status){var x=new Diagnosis();x.id=UUID.randomUUID();x.consultation=c;x.catalogId=catalog;x.type=required(type).toUpperCase();x.description=optional(description);x.status=status==null||status.isBlank()?"ACTIVE":status.trim().toUpperCase();x.diagnosedAt=Instant.now();return x;}UUID getId(){return id;}UUID getCatalogId(){return catalogId;}String getType(){return type;}String getDescription(){return description;}String getStatus(){return status;}Instant getDiagnosedAt(){return diagnosedAt;}}
@Entity @Table(name="consultation_note",schema="consultation") class ConsultationNote{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id",nullable=false)private Consultation consultation;@Column(name="author_id",nullable=false)private UUID authorId;@Column(name="note_type",length=50)private String type;@Column(nullable=false,columnDefinition="text")private String content;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected ConsultationNote(){}static ConsultationNote create(Consultation c,UUID author,String type,String content){var x=new ConsultationNote();x.id=UUID.randomUUID();x.consultation=c;x.authorId=Objects.requireNonNull(author);x.type=required(type).toUpperCase();x.content=required(content);x.createdAt=Instant.now();x.updatedAt=x.createdAt;return x;}UUID getId(){return id;}UUID getAuthorId(){return authorId;}String getType(){return type;}String getContent(){return content;}Instant getCreatedAt(){return createdAt;}Instant getUpdatedAt(){return updatedAt;}}
@Entity @Table(name="clinical_observation",schema="consultation") class ClinicalObservation{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id",nullable=false)private Consultation consultation;@Column(name="author_id")private UUID authorId;@Column(nullable=false,length=100)private String type;@Column(columnDefinition="text")private String value;@Column(columnDefinition="text")private String notes;@Column(name="observed_at",nullable=false)private Instant observedAt;protected ClinicalObservation(){}static ClinicalObservation create(Consultation c,UUID author,String type,String value,String notes,Instant at){var x=new ClinicalObservation();x.id=UUID.randomUUID();x.consultation=c;x.authorId=author;x.type=required(type).toUpperCase();x.value=optional(value);x.notes=optional(notes);if(x.value==null&&x.notes==null)throw new IllegalArgumentException("Observation needs a value or notes");x.observedAt=at==null?Instant.now():at;return x;}UUID getId(){return id;}UUID getAuthorId(){return authorId;}String getType(){return type;}String getValue(){return value;}String getNotes(){return notes;}Instant getObservedAt(){return observedAt;}}
@Entity @Table(name="treatment_plan",schema="consultation") class TreatmentPlan{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id",nullable=false)private Consultation consultation;@Column(nullable=false,columnDefinition="text")private String description;@Column(name="start_date")private LocalDate startDate;@Column(name="end_date")private LocalDate endDate;@Column(nullable=false,length=30)private String status;protected TreatmentPlan(){}static TreatmentPlan create(Consultation c,String description,LocalDate start,LocalDate end,String status){if(start!=null&&end!=null&&end.isBefore(start))throw new IllegalArgumentException("Invalid treatment dates");var x=new TreatmentPlan();x.id=UUID.randomUUID();x.consultation=c;x.description=required(description);x.startDate=start;x.endDate=end;x.status=status==null||status.isBlank()?"ACTIVE":status.trim().toUpperCase();return x;}UUID getId(){return id;}String getDescription(){return description;}LocalDate getStartDate(){return startDate;}LocalDate getEndDate(){return endDate;}String getStatus(){return status;}}
@Entity @Table(name="follow_up",schema="consultation") class FollowUp{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id",nullable=false)private Consultation consultation;@Column(name="recommended_date")private LocalDate date;@Column(columnDefinition="text")private String instructions;@Column(nullable=false,length=30)private String status;protected FollowUp(){}static FollowUp create(Consultation c,LocalDate date,String instructions,String status){var x=new FollowUp();x.id=UUID.randomUUID();x.consultation=c;x.date=date;x.instructions=required(instructions);x.status=status==null||status.isBlank()?"PLANNED":status.trim().toUpperCase();return x;}UUID getId(){return id;}LocalDate getDate(){return date;}String getInstructions(){return instructions;}String getStatus(){return status;}}
final class Values{static String required(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value");return v.trim();}static String optional(String v){return v==null||v.isBlank()?null:v.trim();}}
